-- Resolves public NPC identity and route-approved emotes/raid-marker targets.
-- Secret-aware identity reads are delegated to SecretUtils before constructing macro text.

--- Extract numeric NPC ID from a unit GUID.
-- The default unit is the current target, but we allow overriding so mouseover or other units can be inspected.
function APR:GetTargetID(unit)
    unit = unit or "target"
    return APRSecret:SafeUnitCreatureID(unit)
end--[[APR_DIAG]]; APR.GetTargetID = APRTrace("APR-Core/utils/TargetUtils.lua:11:APR:GetTargetID#1", APR.GetTargetID)--[[/APR_DIAG]]

--- Prevent interactions with forbidden NPCs declared on a step.
-- The function is intentionally defensive: it checks the current target and exits early when no match exists.
function APR:CheckDenyNPC(step)
    if (step and step.DenyNPC) then
        local npc_id, name = self:GetTargetID(), APR:SafeUnitName("target")
        if (npc_id and name) then
            if (npc_id == step.DenyNPC) then
                APR:Debug("APR:CheckDenyNPC() - Deny NPC found")

                C_GossipInfo.CloseGossip()
                C_Timer.After(0.3, --[[APR_DIAG]]APRTrace("APR-Core/utils/TargetUtils.lua:26:callback#3", --[[/APR_DIAG]]function() APR:CloseQuest() end--[[APR_DIAG]])--[[/APR_DIAG]])
                APR:NotYet()
            end
        end
    end
end--[[APR_DIAG]]; APR.CheckDenyNPC = APRTrace("APR-Core/utils/TargetUtils.lua:18:APR:CheckDenyNPC#2", APR.CheckDenyNPC)--[[/APR_DIAG]]

--- Trigger a conditional emote on specific NPCs required by a quest step.
function APR:DoEmote(step)
    if step and step.Emote and not step.Emote.manual then
        if step.EmoteETA and self.GetRouteActionState and self:GetRouteActionState().emoteTimerStarted then return end
        local npc_id = APR:GetTargetID()
        if not step.Emote.npcID or step.Emote.npcID == 0 or npc_id == step.Emote.npcID then
            APR:PerformEmote(step.Emote.emote)
            APR:HandleEmoteETA(step, step.Emote.emote)
        end
    end
end--[[APR_DIAG]]; APR.DoEmote = APRTrace("APR-Core/utils/TargetUtils.lua:34:APR:DoEmote#4", APR.DoEmote)--[[/APR_DIAG]]

function APR:HandleEmoteETA(step, emote)
    if not step or not step.Emote or not step.EmoteETA or not self.GetRouteActionState then return end
    if type(emote) ~= "string" or emote:lower() ~= step.Emote.emote:lower() then return end
    local npcID = step.Emote.npcID
    if npcID and npcID > 0 and self:GetTargetID() ~= npcID then return end
    local state = self:GetRouteActionState()
    if state.emoteTimerStarted then return end
    state.emoteTimerStarted = true
    self.AFK.lastStep = APRData[self.PlayerID][self.ActiveRoute]
    self.AFK:SetAfkTimer(step.EmoteETA)
end--[[APR_DIAG]]; APR.HandleEmoteETA = APRTrace("APR-Core/utils/TargetUtils.lua:45:APR:HandleEmoteETA#5", APR.HandleEmoteETA)--[[/APR_DIAG]]

-- Observe both manually typed emotes and APR's button, without starting a timer
-- merely because the step is displayed or a different emote is performed.
function APR:OnStepEmote(emote)
    local profile = self.settings and self.settings.profile
    local data = APRData and APRData[self.PlayerID]
    local index = data and self.ActiveRoute and data[self.ActiveRoute]
    if not index or not profile or not profile.enableAddon then return end
    self:HandleEmoteETA(self:GetStep(index), emote)
end--[[APR_DIAG]]; APR.OnStepEmote = APRTrace("APR-Core/utils/TargetUtils.lua:59:APR:OnStepEmote#6", APR.OnStepEmote)--[[/APR_DIAG]]

if hooksecurefunc then
    if C_ChatInfo and C_ChatInfo.PerformEmote then
        hooksecurefunc(C_ChatInfo, "PerformEmote", --[[APR_DIAG]]APRTrace("APR-Core/utils/TargetUtils.lua:69:callback#7", --[[/APR_DIAG]]function(emote) APR:OnStepEmote(emote) end--[[APR_DIAG]])--[[/APR_DIAG]])
    end
    if DoEmote then
        hooksecurefunc("DoEmote", --[[APR_DIAG]]APRTrace("APR-Core/utils/TargetUtils.lua:72:callback#8", --[[/APR_DIAG]]function(emote) APR:OnStepEmote(emote) end--[[APR_DIAG]])--[[/APR_DIAG]])
    end
end

--- Perform an emote with a 12.0+ compatible API and legacy fallback.
function APR:PerformEmote(emote)
    if not emote then
        return
    end
    if C_ChatInfo and C_ChatInfo.PerformEmote then
        C_ChatInfo.PerformEmote(emote)
    else
        DoEmote(emote)
    end
    self:OnStepEmote(emote)
end--[[APR_DIAG]]; APR.PerformEmote = APRTrace("APR-Core/utils/TargetUtils.lua:77:APR:PerformEmote#9", APR.PerformEmote)--[[/APR_DIAG]]

---Scans a unit to check if it is an NPC and retrieves NPC information.
---@param unit string The unit token to scan (e.g., "target", "mouseover")
---@param source string The source or context of the scan request
---@return boolean|table Returns true if unit is an NPC with data, false otherwise
function APR:ScanUnitForNPC(unit, source)
    if not APRSecret:CanAccessValue(unit) or not unit then return end
    if not UnitExists(unit) then return end
    if UnitIsPlayer(unit) then return end

    if not (UnitCanAttack("player", unit) or UnitIsFriend("player", unit)) then
        return
    end

    local npcID = APR:GetTargetID(unit)
    if not npcID or APRData.NPCList[npcID] then return end

    local name = APRSecret:SafeUnitName(unit, nil)
    if not name or name == "" or name == UNKNOWN then return end

    APRData.NPCList[npcID] = name

    APR:Debug("NPC map", { npcID, name, source })
    if self.ActiveRoute and self.GetRouteSteps then
        for _, step in ipairs(self:GetRouteSteps(self.ActiveRoute) or {}) do
            if step.TameBeast and step.TameBeast.npcID == npcID then
                if self.event and self.event.QueueStepRefresh then self.event:QueueStepRefresh() end
                if self.questOrderList and self.questOrderList.DelayedUpdate then
                    self.questOrderList:DelayedUpdate(true)
                end
                break
            end
        end
    end
end--[[APR_DIAG]]; APR.ScanUnitForNPC = APRTrace("APR-Core/utils/TargetUtils.lua:93:APR:ScanUnitForNPC#10", APR.ScanUnitForNPC)--[[/APR_DIAG]]

--- Gets the raid icon NPC name for a given NPC ID.
--- @param npcID number The NPC ID to look up
--- @return string|nil The raid icon NPC name, or nil if not found
function APR:GetRaidIconNpcName(npcID)
    if not APRSecret:CanAccessValue(npcID) or type(npcID) ~= "number" then
        return nil
    end
    local name = APRData and APRData.NPCList and APRData.NPCList[npcID]
    if not APRSecret:CanAccessValue(name) then name = nil end
    if not name and C_TooltipInfo and C_TooltipInfo.GetHyperlink then
        local tooltip = C_TooltipInfo.GetHyperlink("unit:Creature-0-0-0-0-" .. npcID .. "-0")
        local lines = APRSecret:CanAccessTable(tooltip) and tooltip.lines
        local first = APRSecret:CanAccessTable(lines) and lines[1]
        local localized = APRSecret:CanAccessTable(first) and first.leftText
        if APRSecret:CanAccessValue(localized) and type(localized) == "string" and localized ~= "" and localized ~= UNKNOWN then
            name = localized
            if APRData then
                APRData.NPCList = APRData.NPCList or {}
                APRData.NPCList[npcID] = name
            end
        end
    end
    if not name and self.GetCurrentStep then
        local step = self:GetCurrentStep()
        if step and step.KillNPC and step.KillNPC.npcID == npcID then name = step.KillNPC.name end
    end
    if not APRSecret:CanAccessValue(name) or type(name) ~= "string" or name == "" or name:find("[\r\n|%[%];]") then return nil end
    return name
end--[[APR_DIAG]]; APR.GetRaidIconNpcName = APRTrace("APR-Core/utils/TargetUtils.lua:127:APR:GetRaidIconNpcName#11", APR.GetRaidIconNpcName)--[[/APR_DIAG]]

--- Finds the unit token for a raid target with the specified NPC ID.
---
--- @param npcID number The NPC ID to search for among raid targets.
--- @return string|nil unitToken The unit token (e.g., "raid1", "raid2") if found, nil otherwise.
---
--- @usage
--- local token = APR:FindRaidIconUnitToken(12345)
--- if token then
---     print("Found unit: " .. token)
--- end
function APR:FindRaidIconUnitToken(npcID)
    if not npcID then return nil end

    if APR:GetTargetID("target") == npcID then
        return "target"
    end

    if not C_NamePlate or not C_NamePlate.GetNamePlates then
        return nil
    end

    for _, plate in ipairs(C_NamePlate.GetNamePlates()) do
        local unit = plate and plate.namePlateUnitToken
        if unit and APR:GetTargetID(unit) == npcID then
            return unit
        end
    end

    return nil
end--[[APR_DIAG]]; APR.FindRaidIconUnitToken = APRTrace("APR-Core/utils/TargetUtils.lua:164:APR:FindRaidIconUnitToken#12", APR.FindRaidIconUnitToken)--[[/APR_DIAG]]

--- Builds a raid icon macro for a specific NPC.
--- @param npcID number The NPC ID to create the macro for
--- @param unitToken string The unit token (e.g., "target", "focus") to apply the macro to
--- @return string The generated macro string
function APR:BuildRaidIconMacro(npcID, unitToken)
    local lines = {}

    if unitToken then
        table.insert(lines, "/target [@" .. unitToken .. ",exists]")
        table.insert(lines, "/tm [@" .. unitToken .. ",exists] 8")
        return table.concat(lines, "\n")
    end

    local name = self:GetRaidIconNpcName(npcID)
    if name then
        table.insert(lines, "/cleartarget")
        table.insert(lines, "/targetexact " .. name)
        table.insert(lines, "/tm [@target,exists] 8")
        return table.concat(lines, "\n")
    end

    return "/tm [@mouseover,exists][@target,exists] 8"
end--[[APR_DIAG]]; APR.BuildRaidIconMacro = APRTrace("APR-Core/utils/TargetUtils.lua:189:APR:BuildRaidIconMacro#13", APR.BuildRaidIconMacro)--[[/APR_DIAG]]
